function Write-Utf8NoBom([string]$Path,[string]$Text){$e=New-Object System.Text.UTF8Encoding($false);[IO.File]::WriteAllText($Path,$Text,$e)}
function Write-Log([string]$Message){if(-not(Test-Path $script:LogDir)){New-Item -ItemType Directory -Force -Path $script:LogDir|Out-Null};$l='[{0}] {1}'-f(Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff'),$Message;Add-Content -LiteralPath $script:LogPath -Value $l -Encoding UTF8;Write-Host $l}
function Get-KeyDerivedId([string]$Key){if([string]::IsNullOrWhiteSpace($Key)){return $null};try{$b=[Convert]::FromBase64String($Key);$h=[Security.Cryptography.SHA256]::Create().ComputeHash($b);$c='abcdefghijklmnop';$s=New-Object Text.StringBuilder;for($i=0;$i-lt16;$i++){[void]$s.Append($c[($h[$i]-shr4)-band15]);[void]$s.Append($c[$h[$i]-band15])};$s.ToString()}catch{return $null}}
function Test-ExtensionPath([string]$Path,[bool]$RequireKeyMatch){try{if([string]::IsNullOrWhiteSpace($Path)){return $false};$f=[IO.Path]::GetFullPath($Path);$mp=Join-Path $f 'manifest.json';if(-not(Test-Path -LiteralPath $mp -PathType Leaf)){return $false};$m=Get-Content -Raw -LiteralPath $mp|ConvertFrom-Json;if(([string]$m.name)-notmatch'TigerIQ Auto Worker'){return $false};if($RequireKeyMatch){$kp=$m.PSObject.Properties['key'];if($null-eq$kp){return $false};if((Get-KeyDerivedId([string]$kp.Value))-ne$script:ExtensionId){return $false}};return $true}catch{return $false}}
function Find-ExtensionPathFromPreferences{$ud=Join-Path $env:LOCALAPPDATA 'Google\Chrome\User Data';if(-not(Test-Path $ud)){return @()};$o=New-Object Collections.Generic.List[string];$ps=Get-ChildItem -LiteralPath $ud -Directory -ErrorAction SilentlyContinue|Where-Object{$_.Name-eq'Default'-or$_.Name-like'Profile *'};foreach($p in $ps){foreach($n in @('Preferences','Secure Preferences')){$f=Join-Path $p.FullName $n;if(-not(Test-Path $f)){continue};for($a=0;$a-lt3;$a++){try{$j=Get-Content -Raw -LiteralPath $f|ConvertFrom-Json;$st=$j.extensions.settings;if($null-eq$st){break};$pr=$st.PSObject.Properties[$script:ExtensionId];if($null-eq$pr){break};$pp=$pr.Value.PSObject.Properties['path'];if($null-eq$pp-or[string]::IsNullOrWhiteSpace([string]$pp.Value)){break};$x=[string]$pp.Value;if(-not[IO.Path]::IsPathRooted($x)){$x=Join-Path $p.FullName $x};if(Test-ExtensionPath $x $false){$o.Add([IO.Path]::GetFullPath($x))};break}catch{Start-Sleep -Milliseconds 250}}}};return @($o|Select-Object -Unique)}
function Find-ExtensionPathFromCommandLine{$o=New-Object Collections.Generic.List[string];try{$ps=Get-CimInstance Win32_Process -Filter "Name='chrome.exe'" -ErrorAction SilentlyContinue;foreach($p in $ps){$cl=[string]$p.CommandLine;if([string]::IsNullOrWhiteSpace($cl)){continue};foreach($m in [regex]::Matches($cl,'--load-extension=(?:"([^"]+)"|([^\s]+))')){$r=if($m.Groups[1].Success){$m.Groups[1].Value}else{$m.Groups[2].Value};foreach($x in($r-split',')){if(Test-ExtensionPath $x $true){$o.Add([IO.Path]::GetFullPath($x))}}}}}catch{};return @($o|Select-Object -Unique)}
function Find-ExtensionPath{$p=@(Find-ExtensionPathFromPreferences);if($p.Count-eq0){$p=@(Find-ExtensionPathFromCommandLine)};if($p.Count-eq0){foreach($x in @('C:\TigerIQ\AutoResumeV6\extension','D:\TigerIQ\AutoResumeV6\extension','F:\TigerIQ\AutoResumeV6\extension','C:\TigerIQ\AutoWorker\extension','D:\TigerIQ\AutoWorker\extension','F:\TigerIQ\AutoWorker\extension')){if(Test-ExtensionPath $x $true){$p+=[IO.Path]::GetFullPath($x)}};$p=@($p|Select-Object -Unique)};if($p.Count-eq0){throw('EXTENSION_PATH_NOT_FOUND_FOR_ID_'+$script:ExtensionId)};if($p.Count-gt1){throw('EXTENSION_PATH_AMBIGUOUS: '+($p-join' | '))};return[string]$p[0]}
function Get-ChromeExecutable{try{$p=Get-CimInstance Win32_Process -Filter "Name='chrome.exe'" -ErrorAction SilentlyContinue|Select-Object -First 1;if($null-ne$p-and-not[string]::IsNullOrWhiteSpace([string]$p.ExecutablePath)-and(Test-Path $p.ExecutablePath)){return[string]$p.ExecutablePath}}catch{};foreach($x in @("$env:ProgramFiles\Google\Chrome\Application\chrome.exe","${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe","$env:LOCALAPPDATA\Google\Chrome\Application\chrome.exe")){if($x-and(Test-Path $x)){return$x}};return$null}
function Copy-DirectoryContent([string]$S,[string]$D){if(-not(Test-Path $D)){New-Item -ItemType Directory -Force -Path $D|Out-Null};Get-ChildItem -LiteralPath $S -Force|ForEach-Object{Copy-Item -LiteralPath $_.FullName -Destination $D -Recurse -Force}}
function Clear-DirectoryContent([string]$P){if(Test-Path $P){Get-ChildItem -LiteralPath $P -Force|Remove-Item -Recurse -Force}}
function Backup-Extension([string]$P){if(-not(Test-Path $script:BackupRootBase)){New-Item -ItemType Directory -Force -Path $script:BackupRootBase|Out-Null};$d=Join-Path $script:BackupRootBase ('v14_2_1_'+(Get-Date -Format 'yyyyMMdd_HHmmss_fff'));New-Item -ItemType Directory -Force -Path $d|Out-Null;Copy-DirectoryContent $P $d;$script:BackupPath=$d;Write-Log('BACKUP_OK path='+$d)}
function Restore-Backup{if($null-eq$script:BackupPath-or$null-eq$script:ExtensionPath){return};Write-Log'ROLLBACK_BEGIN';Clear-DirectoryContent $script:ExtensionPath;Copy-DirectoryContent $script:BackupPath $script:ExtensionPath;Write-Log'ROLLBACK_FILES_RESTORED'}
function Get-ChromeDocuments{Add-Type -AssemblyName UIAutomationClient;Add-Type -AssemblyName UIAutomationTypes;$d=New-Object Collections.Generic.List[object];foreach($p in @(Get-Process chrome -ErrorAction SilentlyContinue)){if($p.MainWindowHandle-eq0){continue};try{$w=[Windows.Automation.AutomationElement]::FromHandle($p.MainWindowHandle);$c=New-Object Windows.Automation.PropertyCondition -ArgumentList @([Windows.Automation.AutomationElement]::ControlTypeProperty,[Windows.Automation.ControlType]::Document);foreach($x in $w.FindAll([Windows.Automation.TreeScope]::Subtree,$c)){$d.Add($x)}}catch{}};return @($d)}
function Invoke-ExtensionReloadAndConfirm([string]$ExpectedVersion){if(-not$script:ChromeWasRunning){return@{Ok=$true;Mode='CHROME_NOT_RUNNING_ON_DISK_ONLY';VersionConfirmed=$false}};if([string]::IsNullOrWhiteSpace($script:ChromeExe)-or-not(Test-Path $script:ChromeExe)){return@{Ok=$false;Mode='CHROME_EXE_NOT_FOUND';VersionConfirmed=$false}};Write-Log'RELOAD_HANDSHAKE_BEGIN chrome_already_running=true';Start-Process -FilePath $script:ChromeExe -ArgumentList ('chrome://extensions/?id='+$script:ExtensionId)|Out-Null;$script:ReloadAttempted=$true;Start-Sleep -Seconds 3;$clicked=$false;for($r=0;$r-lt5-and-not$clicked;$r++){foreach($doc in @(Get-ChromeDocuments)){try{$c=New-Object Windows.Automation.PropertyCondition -ArgumentList @([Windows.Automation.AutomationElement]::ControlTypeProperty,[Windows.Automation.ControlType]::Button);foreach($b in $doc.FindAll([Windows.Automation.TreeScope]::Subtree,$c)){$n=[string]$b.Current.Name;if($n-match'(?i)^\s*(reload|reload extension|tải lại|tai lai|tải lại tiện ích|tai lai tien ich)\s*$'){try{$b.GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke();$clicked=$true;Write-Log('RELOAD_BUTTON_INVOKED name='+$n);break}catch{}}}}catch{};if($clicked){break}};if(-not$clicked){Start-Sleep -Seconds 1}};if(-not$clicked){return@{Ok=$false;Mode='RELOAD_UI_BUTTON_NOT_FOUND';VersionConfirmed=$false}};Start-Sleep -Seconds 3;if([string]::IsNullOrWhiteSpace($ExpectedVersion)){return@{Ok=$true;Mode='ROLLBACK_RELOAD_CLICKED';VersionConfirmed=$false}};$ok=$false;for($r=0;$r-lt5-and-not$ok;$r++){foreach($doc in @(Get-ChromeDocuments)){try{foreach($e in $doc.FindAll([Windows.Automation.TreeScope]::Subtree,[Windows.Automation.Condition]::TrueCondition)){try{if(([string]$e.Current.Name)-match[regex]::Escape($ExpectedVersion)){$ok=$true;break}}catch{}}}catch{};if($ok){break}};if(-not$ok){Start-Sleep -Seconds 1}};if(-not$ok){return@{Ok=$false;Mode='CHROME_UI_VERSION_NOT_CONFIRMED';VersionConfirmed=$false}};return@{Ok=$true;Mode='CHROME_UI_VERSION_CONFIRMED';VersionConfirmed=$true}}
function Invoke-BestEffortRollbackReload{if(-not$script:ChromeWasRunning-or-not$script:ReloadAttempted){return};try{Write-Log'ROLLBACK_RELOAD_ATTEMPT';[void](Invoke-ExtensionReloadAndConfirm '')}catch{Write-Log('ROLLBACK_RELOAD_WARN '+$_.Exception.Message)}}
